)
VALUES ($1, $2, $3, $4, $5, now(), now())
ON CONFLICT (workspace_id, feature_id, document_type) DO UPDATE SET
    source_path   = EXCLUDED.source_path,
    url           = EXCLUDED.url,
    updated_at    = now()
RETURNING id, workspace_id, feature_id, document_type, source_path, url, created_at, updated_at`

type UpsertFeatureDocumentParams struct {
	WorkspaceID  pgtype.UUID
	FeatureID    string
	DocumentType string
	SourcePath   string
	URL          *string
}

func (q *Queries) UpsertFeatureDocument(ctx context.Context, arg UpsertFeatureDocumentParams) (WorkspaceFeatureDocument, error) {
	row := q.db.QueryRow(ctx, upsertFeatureDocument,
		arg.WorkspaceID,
		arg.FeatureID,
		arg.DocumentType,
		arg.SourcePath,
		arg.URL,
	)
	var i WorkspaceFeatureDocument
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.FeatureID,
		&i.DocumentType,
		&i.SourcePath,
		&i.URL,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

const deleteFeatureDocumentsNotIn = `-- name: DeleteFeatureDocumentsNotIn :exec
DELETE FROM workspace_feature_documents
WHERE workspace_id = $1
  AND feature_id   = $2
  AND document_type != ALL($3::text[])`

type DeleteFeatureDocumentsNotInParams struct {
	WorkspaceID   pgtype.UUID
	FeatureID     string
	DocumentTypes []string
}

func (q *Queries) DeleteFeatureDocumentsNotIn(ctx context.Context, arg DeleteFeatureDocumentsNotInParams) error {
	_, err := q.db.Exec(ctx, deleteFeatureDocumentsNotIn, arg.WorkspaceID, arg.FeatureID, arg.DocumentTypes)
	return err
}

const deleteAllFeatureDocuments = `-- name: DeleteAllFeatureDocuments :exec
DELETE FROM workspace_feature_documents
WHERE workspace_id = $1 AND feature_id = $2`

type DeleteAllFeatureDocumentsParams struct {
	WorkspaceID pgtype.UUID
	FeatureID   string
}

func (q *Queries) DeleteAllFeatureDocuments(ctx context.Context, arg DeleteAllFeatureDocumentsParams) error {
	_, err := q.db.Exec(ctx, deleteAllFeatureDocuments, arg.WorkspaceID, arg.FeatureID)
	return err
}

